export type InlineStartTracker = {
  begin(): void;
  end(): void;
  isStarting(): boolean;
};

export const createInlineStartTracker = (): InlineStartTracker => {
  let inFlight = 0;
  return {
    begin: () => {
      inFlight += 1;
    },
    end: () => {
      inFlight = Math.max(0, inFlight - 1);
    },
    isStarting: () => inFlight > 0,
  };
};
